
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_c09x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_c09x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.223934520901911e+00, -4.140962364672217e+00, -4.024750267724259e+00, -3.863878928620136e+00, -3.644913591571326e+00, -3.354026957044653e+00, -2.980866759547806e+00, -2.525703511541421e+00, -2.009822138007344e+00, -1.483682351490825e+00, -1.006171728660322e+00, -6.896580102551881e-01, -5.948270079404808e-01, -4.851936920009052e-01, -3.475422922249034e-01, -2.241759559622936e-01, -1.395397618368517e-01, -6.075753624774687e-02, -1.346686032800458e-02, -1.513528288388655e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


